static void Texture(string path,bool normal,bool linear){var t=(TextureImporter)AssetImporter.GetAtPath(path);t.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;t.sRGBTexture=!linear&&!normal;t.maxTextureSize=2048;t.mipmapEnabled=true;t.wrapModeU=TextureWrapMode.Repeat;t.wrapModeV=TextureWrapMode.Clamp;t.textureCompression=TextureImporterCompression.CompressedHQ;t.alphaSource=TextureImporterAlphaSource.FromInput;t.SaveAndReimport();}
public static string Main(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var s=SceneManager.GetActiveScene();var config=JObject.Parse(File.ReadAllText(R+"/application_facts.json"));var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var player=all.Where(t=>t.parent==null&&t.name.StartsWith("Player")).SelectMany(t=>t.GetComponentsInChildren<Renderer>(true)).Select(r=>new{r=r,e=r.enabled}).ToArray();var renderers=((JArray)config["walls"]).Select(a=>new{renderer=all.First(t=>P(t)==(string)a["path"]).GetComponent<Renderer>(),old=AssetDatabase.LoadAssetAtPath<Material>((string)a["previousMaterial"])}).ToArray();var current=renderers.Select(x=>x.renderer.sharedMaterial).ToArray();try{foreach(var r in player)r.r.enabled=false;foreach(var r in renderers)r.renderer.sharedMaterial=r.old;Render("NorthWall_before",new Vector3(-2.9f,1.75f,5.3f),new Vector3(-3.5f,1.55f,1.88f));Render("CellWall_before",new Vector3(.1f,1.65f,9.4f),new Vector3(1.5f,1.3f,11.1f));for(int k=0;k<renderers.Length;k++)renderers[k].renderer.sharedMaterial=current[k];Render("NorthWall_after",new Vector3(-2.9f,1.75f,5.3f),new Vector3(-3.5f,1.55f,1.88f));Render("CellWall_after",new Vector3(.1f,1.65f,9.4f),new Vector3(1.5f,1.3f,11.1f));}finally{for(int k=0;k<renderers.Length;k++)renderers[k].renderer.sharedMaterial=current[k];foreach(var r in player)r.r.enabled=r.e;}return "Comparison renders updated; player and material references restored";}}
